import { UnknownReferenceError } from "./errors.js";

/**
 * @typedef {object} Customer
 * @property {string} customerId
 * @property {string} name
 * @property {string} country
 */

/** Customers by id, for lookups. */
export function buildCustomerIndex(records) {
  const index = new Map();
  for (const record of records) {
    index.set(record.customerId, record);
  }
  return index;
}

/** The customer with this id; `referencedBy` names the record that asked for it, for the error message. */
export function requireCustomer(index, id, referencedBy) {
  const customer = index.get(id);
  if (!customer) {
    throw new UnknownReferenceError("customer", id, referencedBy);
  }
  return customer;
}
import { readFileSync } from "node:fs";
import { join } from "node:path";

function readJson(directory, file) {
  return JSON.parse(readFileSync(join(directory, file), "utf8"));
}

export function loadInvoices(directory) {
  return readJson(directory, "invoices.json");
}

/** The customers of both systems in one list: billing first, then the CRM. */
export function loadCustomerRecords(directory) {
  return [
    ...readJson(directory, "billing-customers.json"),
    ...readJson(directory, "crm-customers.json"),
  ];
}
/** A record refers to something that does not exist, for example an invoice to an unknown customer. */
export class UnknownReferenceError extends Error {
  constructor(kind, id, referencedBy) {
    const origin = referencedBy ? ` (referenced by ${referencedBy})` : "";
    super(`Unknown ${kind} "${id}"${origin}`);
    this.name = "UnknownReferenceError";
    this.kind = kind;
    this.id = id;
  }
}
import { requireCustomer } from "./customers.js";
import { invoiceTotalCents } from "./invoices.js";

/** The invoices of one customer with their total, for the customer statement page. */
export function customerStatement(invoices, customers, customerId) {
  const customer = requireCustomer(customers, customerId);
  const own = invoices.filter((invoice) => invoice.customerId === customerId);
  return {
    customer,
    invoiceIds: own.map((invoice) => invoice.id),
    totalCents: own.reduce((sum, invoice) => sum + invoiceTotalCents(invoice), 0),
  };
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { buildCustomerIndex, requireCustomer } from "../src/customers.js";
import { UnknownReferenceError } from "../src/errors.js";

const acme = { customerId: "C-1", name: "Acme", country: "DE" };
const nordwind = { customerId: "C-2", name: "Nordwind", country: "US" };

test("buildCustomerIndex finds customers by id", () => {
  const index = buildCustomerIndex([acme, nordwind]);
  assert.equal(index.get("C-1"), acme);
  assert.equal(index.get("C-2"), nordwind);
  assert.equal(index.size, 2);
});

test("requireCustomer returns the customer", () => {
  assert.equal(requireCustomer(buildCustomerIndex([acme]), "C-1"), acme);
});

test("requireCustomer names the unknown customer and who asked for it", () => {
  const index = buildCustomerIndex([acme]);
  assert.throws(
    () => requireCustomer(index, "C-9", "invoice INV-7"),
    (error) =>
      error instanceof UnknownReferenceError &&
      error.message === 'Unknown customer "C-9" (referenced by invoice INV-7)',
  );
});
# invoice-export

Turns the invoices of the billing system into the CSV file the accounting team imports every month.

## Usage

```
npm run export > invoices.csv
```

This runs `node src/cli.js data`: it reads `invoices.json`, `billing-customers.json` and `crm-customers.json` from
the given directory (default `data/`) and prints one CSV row per invoice, in the order of `invoices.json`.

The customers come from two systems. `billing-customers.json` is exported by the billing system, and
`crm-customers.json` holds the customers that were created in the CRM. Both are read as they are delivered. The
accounting import expects the CSV columns `invoice_id,customer,issued_on,total`, so the format must not change.

## Tests

```
npm test
```

Plain `node --test`, no dependencies. Tests live in `tests/`.

## Conventions

- Money is handled in integer cents and formatted only at the edge (`src/money.js`).
- A reference to something that does not exist, such as an unknown customer, is a data error. It is reported with
  `UnknownReferenceError` naming what was not found (see `requireCustomer`), and the CLI then exits with status 1
  and prints nothing to stdout. The export never skips a record or prints a placeholder for it: a file with a
  missing invoice is worse for accounting than no file.
